@code {
    [Parameter, EditorRequired] public int Index { get; set; }
    [Parameter, EditorRequired] public string Name { get; set; } = "";
    [Parameter, EditorRequired] public string Relationship { get; set; } = "";
    [Parameter, EditorRequired] public string Email { get; set; } = "";
