    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<ReferenceChangeArgs> OnChanged { get; set; }

    private void NameChanged(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(new(Index, Name: e.Value?.ToString()));

    private void RelationshipChanged(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(new(Index, Relationship: e.Value?.ToString()));

    private void EmailChanged(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(new(Index, Email: e.Value?.ToString()));

    private void PhoneChanged(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(new(Index, Phone: e.Value?.ToString()));

    public record ReferenceChangeArgs(
