@namespace sv_37f0d9f6bab24d7490e5fb51302c4ac3.Components.JobApplication

<div class="step-content">
    <h2>Personal Information</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" @bind="FullName" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" @bind="Email" @bind:event="oninput" />
        @if (!string.IsNullOrEmpty(EmailError))
        {
            <span class="field-error">@EmailError</span>
        }
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" @bind="Phone" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" @bind="Address" @bind:event="oninput"></textarea>
    </div>

    <div class="step-actions">
        <button type="button" class="btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<PersonalInfoResult> OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string? ErrorMessage;
    private string? EmailError;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ErrorMessage = null;
        EmailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        IsValidating = true;
        try
        {
            var isValidEmail = await ValidateEmail(Email);
            if (!isValidEmail)
            {
                EmailError = "Please enter a valid email address.";
                return;
            }

            await OnNext.InvokeAsync(new PersonalInfoResult(FullName, Email, Phone, Address));
        }
        finally
        {
            IsValidating = false;
        }
    }

    public record PersonalInfoResult(string FullName, string Email, string Phone, string Address);
}

@namespace sv_37f0d9f6bab24d7490e5fb51302c4ac3.Components.JobApplication

<div class="step-content">
    <h2>Work History</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var entry = Entries[i];
        <WorkEntryForm
            Index="i"
            Company="@entry.Company"
            Title="@entry.Title"
            StartDate="@entry.StartDate"
            EndDate="@entry.EndDate"
            Description="@entry.Description"
            IsCurrent="@entry.IsCurrent"
            ShowRemove="@(Entries.Count > 1)"
            OnRemove="() => RemoveEntry(entry)"
            OnChanged="HandleEntryChanged" />
    }

    <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    <div class="step-actions">
        <button type="button" class="btn-secondary" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<List<WorkEntryModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    protected override void OnInitialized()
    {
        if (Entries.Count == 0)
            Entries.Add(new WorkEntryModel());
    }

    private void AddEntry() => Entries.Add(new WorkEntryModel());

    private void RemoveEntry(WorkEntryModel entry) => Entries.Remove(entry);

    private void HandleEntryChanged(WorkEntryForm.WorkEntryChangeArgs args)
    {
        if (args.Index < 0 || args.Index >= Entries.Count) return;
        var entry = Entries[args.Index];

        if (args.Company is not null) entry.Company = args.Company;
        if (args.Title is not null) entry.Title = args.Title;
        if (args.StartDate is not null) entry.StartDate = args.StartDate.Value;
        if (args.EndDate is not null) entry.EndDate = args.EndDate.Value;
        if (args.IsCurrent is not null)
        {
            entry.IsCurrent = args.IsCurrent.Value;
            if (entry.IsCurrent) entry.EndDate = null;
        }
        if (args.Description is not null) entry.Description = args.Description;
    }

    private Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate == default)
            {
                ErrorMessage = "Each position requires at least a company name, job title, and start date.";
                return Task.CompletedTask;
            }
        }

        return OnNext.InvokeAsync(Entries);
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

@namespace sv_37f0d9f6bab24d7490e5fb51302c4ac3.Components.JobApplication

<div class="step-content">
    <h2>References</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var reference = References[i];
        <ReferenceForm
            Index="i"
            Name="@reference.Name"
            Relationship="@reference.Relationship"
            Email="@reference.Email"
            Phone="@reference.Phone"
            ShowRemove="@(References.Count > 2)"
            OnRemove="() => RemoveReference(reference)"
            OnChanged="HandleReferenceChanged" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    <div class="step-actions">
        <button type="button" class="btn-secondary" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    protected override void OnInitialized()
    {
        if (References.Count == 0)
        {
            References.Add(new ReferenceModel());
            References.Add(new ReferenceModel());
        }
    }

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(ReferenceModel reference)
    {
        if (References.Count > 2)
            References.Remove(reference);
    }

    private void HandleReferenceChanged(ReferenceForm.ReferenceChangeArgs args)
    {
        if (args.Index < 0 || args.Index >= References.Count) return;
        var reference = References[args.Index];

        if (args.Name is not null) reference.Name = args.Name;
        if (args.Relationship is not null) reference.Relationship = args.Relationship;
        if (args.Email is not null) reference.Email = args.Email;
        if (args.Phone is not null) reference.Phone = args.Phone;
    }

    private Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var reference in References)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) ||
                string.IsNullOrWhiteSpace(reference.Relationship) ||
                string.IsNullOrWhiteSpace(reference.Email))
            {
                ErrorMessage = "Each reference requires at least a name, relationship, and email.";
                return Task.CompletedTask;
            }
        }

        return OnNext.InvokeAsync(References);
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

@namespace sv_37f0d9f6bab24d7490e5fb51302c4ac3.Components.JobApplication

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label>Write your cover letter</label>
        <textarea rows="12" maxlength="@MaxLength" @bind="CoverLetter" @bind:event="oninput"
                  placeholder="Tell us why you're a great fit for this role..."></textarea>
        <span class="char-count">@CoverLetter.Length / @MaxLength characters</span>
    </div>

    <div class="step-actions">
        <button type="button" class="btn-secondary" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private Task HandleNext() => OnNext.InvokeAsync(CoverLetter);
}

@namespace sv_37f0d9f6bab24d7490e5fb51302c4ac3.Components.JobApplication

<div class="step-content">
    <h2>Review & Submit</h2>

    @if (IsSubmitted)
    {
        <div class="confirmation">
            <h3>&#10003; Application Submitted Successfully!</h3>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will review your application and get back to you.</p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="error-message">@ErrorMessage</div>
        }

        <section class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button type="button" class="btn-link" @onclick="() => OnEdit.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Full Name</dt><dd>@FullName</dd>
                <dt>Email</dt><dd>@Email</dd>
                <dt>Phone</dt><dd>@Phone</dd>
                <dt>Address</dt><dd>@Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button type="button" class="btn-link" @onclick="() => OnEdit.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <span class="review-dates">
                        @entry.StartDate.ToString("MMM yyyy") &ndash;
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </section>

