@namespace sv_37f0d9f6bab24d7490e5fb51302c4ac3.Components.JobApplication

<fieldset class="work-entry">
    <legend>Position @(Index + 1)</legend>

    @if (ShowRemove)
    {
        <button type="button" class="btn-remove" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
    }

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Company" @onchange="e => CompanyChanged(e)" required />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Title" @onchange="e => TitleChanged(e)" required />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@StartDateString" @onchange="e => StartDateChanged(e)" required />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@EndDateString" @onchange="e => EndDateChanged(e)" disabled="@IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="e => IsCurrentChanged(e)" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Description" @onchange="e => DescriptionChanged(e)"></textarea>
    </div>
</fieldset>

@code {
    [Parameter, EditorRequired] public int Index { get; set; }
    [Parameter, EditorRequired] public string Company { get; set; } = "";
    [Parameter, EditorRequired] public string Title { get; set; } = "";
    [Parameter, EditorRequired] public DateTime StartDate { get; set; }
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter, EditorRequired] public string Description { get; set; } = "";
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryChangeArgs> OnChanged { get; set; }

    private string StartDateString => StartDate == default ? "" : StartDate.ToString("yyyy-MM-dd");
    private string EndDateString => EndDate?.ToString("yyyy-MM-dd") ?? "";

    private void CompanyChanged(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(new(Index, Company: e.Value?.ToString()));

    private void TitleChanged(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(new(Index, Title: e.Value?.ToString()));

    private void StartDateChanged(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
            OnChanged.InvokeAsync(new(Index, StartDate: date));
    }

    private void EndDateChanged(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
            OnChanged.InvokeAsync(new(Index, EndDate: date));
    }

    private void IsCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        OnChanged.InvokeAsync(new(Index, IsCurrent: isCurrent));
    }

    private void DescriptionChanged(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(new(Index, Description: e.Value?.ToString()));

    public record WorkEntryChangeArgs(
        int Index,
        string? Company = null,
        string? Title = null,
        DateTime? StartDate = null,
        DateTime? EndDate = null,
        bool? IsCurrent = null,
        string? Description = null);
}

