@namespace sv_37f0d9f6bab24d7490e5fb51302c4ac3.Components.JobApplication

<div class="step-content">
    <h2>References</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var reference = References[i];
        <ReferenceForm
            Index="i"
            Name="@reference.Name"
            Relationship="@reference.Relationship"
            Email="@reference.Email"
            Phone="@reference.Phone"
            ShowRemove="@(References.Count > 2)"
            OnRemove="() => RemoveReference(reference)"
            OnChanged="HandleReferenceChanged" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    <div class="step-actions">
        <button type="button" class="btn-secondary" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    protected override void OnInitialized()
    {
        if (References.Count == 0)
        {
            References.Add(new ReferenceModel());
            References.Add(new ReferenceModel());
        }
    }

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(ReferenceModel reference)
    {
        if (References.Count > 2)
            References.Remove(reference);
    }

    private void HandleReferenceChanged(ReferenceForm.ReferenceChangeArgs args)
    {
        if (args.Index < 0 || args.Index >= References.Count) return;
        var reference = References[args.Index];

        if (args.Name is not null) reference.Name = args.Name;
        if (args.Relationship is not null) reference.Relationship = args.Relationship;
        if (args.Email is not null) reference.Email = args.Email;
        if (args.Phone is not null) reference.Phone = args.Phone;
    }

    private Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var reference in References)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) ||
                string.IsNullOrWhiteSpace(reference.Relationship) ||
                string.IsNullOrWhiteSpace(reference.Email))
            {
                ErrorMessage = "Each reference requires at least a name, relationship, and email.";
                return Task.CompletedTask;
            }
        }

        return OnNext.InvokeAsync(References);
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

