    font-size: 0.85rem;
    color: #6c757d;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem 2rem;
    background: #d4edda;
    border-radius: 8px;
}

.confirmation h3 {
    color: #155724;
