+
+    private void HandleWorkHistoryNext(List<WorkHistoryStep.WorkEntryModel> entries)
+    {
+        workEntries = entries;
+        completedSteps.Add(1);
+        currentStep = 2;
+    }
+
+    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> refs)
+    {
+        references = refs;
+        completedSteps.Add(2);
+        currentStep = 3;
+    }
+
+    private void HandleCoverLetterNext(string letter)
+    {
+        coverLetter = letter;
+        completedSteps.Add(3);
+        currentStep = 4;
+    }
+
+    private async Task HandleSubmit()
+    {
+        isSubmitting = true;
+        submitError = null;
+
+        try
+        {
+            var application = new JobApplication(
+                new PersonalInfo(fullName, email, phone, address),
+                new WorkHistory(workEntries.Select(e => new WorkEntry(
+                    e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
+                )).ToList()),
+                references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
+                coverLetter
+            );
+
+            applicationId = await ApplicationService.SubmitApplicationAsync(application);
+            isSubmitted = true;
+            completedSteps.Add(4);
+        }
+        catch (Exception ex)
+        {
+            submitError = $"Submission failed: {ex.Message}. Please try again.";
+        }
+        finally
+        {
+            isSubmitting = false;
+        }
+    }
